  await page.waitForFunction(()=>!SCP.busy&&SCP.state.providerCampaign.incidents.some(x=>x.status==='resolved')&&SCP.state.providerCampaign.projects.some(x=>x.operationId==='repair'&&x.status==='complete'),null,{timeout:60000});await click(page,'[data-provider-action="pause"]');await step('repair-settled');
