async function runOwnershipAndPersistence(baseUrl){
 const row={id:'ownership-persistence',status:'running',steps:[],errors:[]};report.journeys.push(row);fs.mkdirSync(path.join(OUT,row.id),{recursive:true});
 const ctx=await browser.newContext({viewport:{width:1366,height:768},acceptDownloads:true,reducedMotion:'reduce'});let owner,observer;
 try{
  owner=await ctx.newPage();await owner.goto(baseUrl);await owner.waitForSelector('[data-provider-action="show-new-game"]');await startNew(owner,{plan:'swift',id:'lock-owner'});
  const saved=await readState(owner);row.steps.push({name:'owner-created',clock:saved.clock,revision:saved.revision});await snap(owner,row,'owner-created');
  observer=await ctx.newPage();await observer.goto(baseUrl);await observer.waitForSelector('[data-provider-action="open"]');await click(observer,'[data-provider-action="open"]');await observer.waitForTimeout(100);const denied=await observer.evaluate(()=>({locked:SCP.locked,state:!!SCP.state,warning:SCP.error,locks:!!navigator.locks,seq:SCP.seq})),ownerState=await owner.evaluate(()=>({locked:SCP.locked,clock:SCP.state?.clock,seq:SCP.seq}));assert.equal(denied.locked,false,`second tab must not acquire the active career lock: ${JSON.stringify({denied,ownerState})}`);assert.equal(denied.state,true,'second tab should display the current read-only save');assert.equal(denied.seq,ownerState.seq);row.steps.push({name:'second-tab-read-only',...denied});await snap(observer,row,'second-tab-read-only');
  await click(owner,'[data-provider-action="drawer"][data-provider-value="menu"]');await click(owner,'[data-provider-action="close"]');await click(observer,'[data-provider-action="drawer"][data-provider-value="menu"]');await click(observer,'[data-provider-action="close"]');await click(observer,'[data-provider-action="open"]');await observer.waitForFunction(()=>SCP.locked&&!!SCP.state,null,{timeout:15000});const reopened=await readState(observer);assert.equal(reopened.clock,saved.clock);assert.equal(reopened.revision,saved.revision);row.steps.push({name:'ownership-reopened',clock:reopened.clock,revision:reopened.revision,locked:true});await snap(observer,row,'ownership-reopened');
  await click(observer,'[data-provider-action="drawer"][data-provider-value="finance"]');const [download]=await Promise.all([observer.waitForEvent('download'),click(observer,'[data-provider-action="export"]')]);const file=await download.path(),exported=JSON.parse(fs.readFileSync(file,'utf8'));assert.equal(exported.revision,reopened.revision);await snap(observer,row,'exported');
  await click(observer,'[data-provider-action="import"]');const area=observer.locator('[data-provider-import]');await area.fill(JSON.stringify(exported));await click(observer,'[data-provider-action="import-confirm"]');const imported=await readState(observer);assert.equal(imported.clock,reopened.clock);assert.equal(imported.revision,reopened.revision);row.steps.push({name:'save-export-import',clock:imported.clock,revision:imported.revision});await snap(observer,row,'save-export-import');
  await click(observer,'[data-provider-action="drawer"][data-provider-value="menu"]');await click(observer,'[data-provider-action="close"]');await observer.close();observer=null;
  const fallback=await ctx.newPage();await fallback.addInitScript(()=>Object.defineProperty(window,'Worker',{value:undefined,configurable:true}));await fallback.goto(baseUrl);await fallback.waitForSelector('[data-provider-action="show-new-game"]');await startNew(fallback,{plan:'swift',id:'worker-fallback'});await click(fallback,'[data-provider-action="speed"][data-provider-value="8"]');await fallback.waitForFunction(()=>SCP.state.clock>0,null,{timeout:15000});await click(fallback,'[data-provider-action="pause"]');const tick=await fallback.evaluate(()=>({clock:SCP.state.clock,worker:typeof Worker,locked:SCP.locked,revision:SCP.state.revision}));assert.equal(tick.worker,'undefined');assert.ok(tick.clock>0);row.steps.push({name:'worker-disabled-real-clock-fallback',...tick});await snap(fallback,row,'worker-disabled-real-clock-fallback');
  await fallback.evaluate(async()=>{await navigator.serviceWorker.ready;});if(!await fallback.evaluate(()=>!!navigator.serviceWorker.controller)){await fallback.reload();await fallback.waitForFunction(()=>!!navigator.serviceWorker.controller,null,{timeout:15000});}const beforeOffline=await readState(fallback);await ctx.setOffline(true);await fallback.reload({waitUntil:'domcontentloaded'});await fallback.waitForSelector('[data-provider-action="open"]');await click(fallback,'[data-provider-action="open"]');await fallback.waitForFunction(()=>SCP.locked&&!!SCP.state,null,{timeout:15000});const offline=await readState(fallback);assert.equal(offline.clock,beforeOffline.clock);assert.equal(offline.revision,beforeOffline.revision);row.steps.push({name:'service-worker-prefixed-offline-reload',clock:offline.clock,revision:offline.revision,controller:await fallback.evaluate(()=>!!navigator.serviceWorker.controller),scope:await fallback.evaluate(()=>navigator.serviceWorker.controller?.scriptURL)});await snap(fallback,row,'service-worker-prefixed-offline-reload');await ctx.setOffline(false);await fallback.close();row.status='passed';
 }catch(error){row.status='failed';row.failure=String(error.stack||error);if(owner)try{await snap(owner,row,'ownership-failure');}catch{}throw error;}
 finally{await ctx.close();}
}
async function runKeyboardJourney(baseUrl){
 const row={id:'keyboard-smb-opening',plan:'swift',viewport:{width:1366,height:768},steps:[],status:'running',errors:[]};report.journeys.push(row);fs.rmSync(path.join(OUT,row.id),{recursive:true,force:true});fs.mkdirSync(path.join(OUT,row.id),{recursive:true,force:true});
 const context=await browser.newContext({viewport:row.viewport,reducedMotion:'reduce'}),page=await context.newPage();page.setDefaultTimeout(15000);page.on('pageerror',e=>row.errors.push(`pageerror:${e.message}`));
 const tabUntil=async(selector,max=300)=>{for(let i=0;i<max;i++){if(await page.evaluate(sel=>!!document.activeElement?.matches(sel),selector))return i;await page.keyboard.press('Tab');}throw new Error(`keyboard focus did not reach ${selector} in ${max} Tab presses`);};
 const enter=async selector=>{const tabs=await tabUntil(selector);await page.keyboard.press('Enter');return tabs;};
 const activate=async(selector,check)=>{const tabs=await tabUntil(selector);for(const key of ['Enter','Space']){await page.keyboard.press(key);await page.waitForTimeout(75);if(await page.evaluate(check))return {tabs,key};}const detail=await page.evaluate(()=>({active:document.activeElement?.outerHTML?.slice(0,180),drawer:SOC_PROVIDER_UI.view().drawer,quoteModal:SOC_PROVIDER_UI.view().quoteModal,error:SCP.error}));throw new Error(`keyboard activation failed for ${selector}: ${JSON.stringify(detail)}`);};
 const modalCommit=async()=>{await activate('[data-provider-action="confirm-quote"]',()=>!SOC_PROVIDER_UI.view().quoteModal);};
 const step=async name=>{const state=await readState(page),view=await page.evaluate(()=>({active:document.activeElement?.outerHTML?.slice(0,120),viewport:innerWidth,documentWidth:document.documentElement.scrollWidth,reducedMotion:matchMedia('(prefers-reduced-motion: reduce)').matches}));assert.ok(view.documentWidth<=view.viewport);assert.equal(view.reducedMotion,true);row.steps.push({name,...state,view});await snap(page,row,name);};
 const advance=async predicate=>{await enter('[data-provider-action="speed"][data-provider-value="8"]');await page.waitForFunction(predicate,null,{timeout:120000});if(await page.evaluate(()=>SCP.speed>0)){await enter('[data-provider-action="pause"]');await page.keyboard.press('Enter');}};
 try{
  await page.goto(baseUrl);await page.waitForSelector('[data-provider-action="show-new-game"]');await enter('[data-provider-action="show-new-game"]');await page.keyboard.press('Enter');await tabUntil('[data-provider-form="new-game"] [name="providerName"]');await page.keyboard.press('Control+A');await page.keyboard.type('Keyboard Orchard MSP');await tabUntil('[data-provider-form="new-game"] button[type="submit"]');await page.keyboard.press('Enter');await page.waitForFunction(()=>!!SCP.state?.providerCampaign&&SCP.locked,null,{timeout:20000});await step('keyboard-career-paused');
  await activate('[data-provider-action="drawer"][data-provider-value="deals"]',()=>SOC_PROVIDER_UI.view().drawer==='deals');await activate('[data-provider-action="quote"][data-offer="starter"][data-plan="swift"]',()=>SOC_PROVIDER_UI.view().quoteModal);await page.locator('[data-provider-action="confirm-quote"]:visible').first().waitFor({state:'visible'});await modalCommit();
  await advance(()=>SCP.state.providerCampaign.customers[0].stages.base?.status==='effective');await step('keyboard-base-effective');
  await activate('[data-provider-action="drawer-close"]',()=>!SOC_PROVIDER_UI.view().sheetOpen);await activate('.provider-map-node[data-provider-action="select-customer"][data-id="starter-customer"]',()=>SOC_PROVIDER_UI.view().selection?.customerId==='starter-customer');await activate('.provider-inspector [data-provider-action="quote"][data-stage="carrier"]',()=>SOC_PROVIDER_UI.view().quoteModal);await page.locator('[data-provider-action="confirm-quote"]:visible').first().waitFor({state:'visible'});await modalCommit();await advance(()=>SCP.state.providerCampaign.customers[0].stages.carrier?.status==='effective');await step('keyboard-carrier-effective');
  await activate('.provider-inspector [data-provider-action="quote"][data-stage="partner"]',()=>SOC_PROVIDER_UI.view().quoteModal);await page.locator('[data-provider-action="confirm-quote"]:visible').first().waitFor({state:'visible'});await modalCommit();await advance(()=>SCP.state.providerCampaign.customers[0].stages.partner?.status==='effective');await step('keyboard-partner-effective');
  await enter('[data-provider-action="speed"][data-provider-value="8"]');await page.keyboard.press('Enter');await page.waitForFunction(()=>SCP.state.providerCampaign.jobs.some(j=>j.customerId==='starter-customer'&&j.status==='completed')&&SCP.state.providerCampaign.incidents.some(i=>i.status==='active'),null,{timeout:120000});assert.equal(await page.evaluate(()=>SCP.speed),0,'new active incident pauses the simulation');await step('keyboard-work-and-incident-paused');
  await enter('[data-provider-action="drawer"][data-provider-value="incidents"]');await page.keyboard.press('Enter');await activate('[data-provider-action="select-incident"]',()=>!!SOC_PROVIDER_UI.view().selection?.incidentId);await enter('.provider-inspector [data-provider-action="ack-incident"]');await page.waitForFunction(()=>SCP.state.providerCampaign.incidents.some(i=>i.status==='acknowledged'),null,{timeout:15000});await step('keyboard-incident-acknowledged');row.status='passed';row.keyboardOnly=true;
 }catch(error){row.status='failed';row.failure=String(error.stack||error);try{await step('failure');}catch{}throw error;}finally{await context.close();}
}
