  await selectMapCustomer(page);await openOperation(page,'automation');await page.locator('.provider-modal[role="dialog"]').waitFor({state:'visible'});const textContent=await page.locator('.provider-modal[role="dialog"]').innerText(),quote=await page.evaluate(()=>structuredClone(SOC_PROVIDER_UI.view().quote));assert.ok(quote.commercial.automation);assert.match(textContent,/starter-customer/);assert.match(textContent,/2 repairs/);assert.match(textContent,/A\$80 each/);assert.match(textContent,/A\$160/);assert.match(textContent,/Cash after commitment/);await snap(page,row,'automation-assurance-quote');await click(page,'[data-provider-action="cancel-quote"]');const state=await readState(page);assert.ok(!state.projects.some(p=>p.operationId==='automation'));row.status='passed';row.quote=quote.commercial.automation;
