async function runMobileHudJourney(baseUrl){
 const row={id:'mobile-hud-opening',viewport:{width:390,height:844},steps:[],status:'running'};report.journeys.push(row);fs.rmSync(path.join(OUT,row.id),{recursive:true,force:true});fs.mkdirSync(path.join(OUT,row.id),{recursive:true});
 const context=await browser.newContext({viewport:row.viewport,reducedMotion:'reduce'}),page=await context.newPage();page.setDefaultTimeout(15000);
 try{
  await page.goto(baseUrl);await page.waitForSelector('[data-provider-action="show-new-game"]');await startNew(page,{plan:'swift',id:row.id});const metrics=await page.evaluate(()=>{const hud=document.querySelector('.provider-hud'),stats=[...document.querySelectorAll('.provider-stat')],clock=document.querySelector('.provider-time'),bounds=x=>{const r=x.getBoundingClientRect(),s=getComputedStyle(x);return {left:r.left,right:r.right,top:r.top,bottom:r.bottom,width:r.width,height:r.height,visible:r.width>0&&r.height>0&&s.display!=='none'&&s.visibility!=='hidden'}};return {viewport:innerWidth,documentWidth:document.documentElement.scrollWidth,hudClient:hud.clientWidth,hudScroll:hud.scrollWidth,hudHeight:hud.getBoundingClientRect().height,stats:stats.map(x=>({label:x.innerText,...bounds(x)})),clock:bounds(clock),clockLabel:clock.innerText};});assert.ok(metrics.documentWidth<=metrics.viewport,`mobile page overflow ${metrics.documentWidth}`);assert.ok(metrics.hudScroll<=metrics.hudClient,`mobile HUD should not scroll horizontally (${metrics.hudScroll}>${metrics.hudClient})`);assert.ok(metrics.stats.length>=4);assert.ok(metrics.stats.every(x=>x.visible&&x.left>=0&&x.right<=metrics.viewport),`all mobile business stats visible: ${JSON.stringify(metrics.stats)}`);assert.ok(metrics.clock.visible&&metrics.clock.left>=0&&metrics.clock.right<=metrics.viewport,`clock and speed visible: ${JSON.stringify(metrics.clock)}`);await snap(page,row,'mobile-opening');
  const selector='[data-provider-action="speed"][data-provider-value="8"]';for(let i=0;i<300&&!await page.evaluate(s=>!!document.activeElement?.matches(s),selector);i++)await page.keyboard.press('Tab');assert.equal(await page.evaluate(s=>!!document.activeElement?.matches(s),selector),true,'keyboard Tab can focus mobile 8× speed');const before=await page.evaluate(()=>SCP.state.clock);await page.keyboard.press('Enter');await page.waitForFunction(t=>SCP.state.clock>t,before,{timeout:15000});assert.equal(await page.evaluate(()=>document.activeElement?.dataset.providerAction==='speed'&&document.activeElement?.dataset.providerValue==='8'),true,'speed-button focus survives real mobile clock tick');const focused=await page.evaluate(()=>{const hud=document.querySelector('.provider-hud'),button=document.activeElement,r=button.getBoundingClientRect();return {clock:SCP.state.clock,active:button.outerHTML,hudHeight:hud.getBoundingClientRect().height,hudClient:hud.clientWidth,hudScroll:hud.scrollWidth,button:{left:r.left,right:r.right,top:r.top,bottom:r.bottom},documentWidth:document.documentElement.scrollWidth,viewport:innerWidth}});assert.ok(focused.hudScroll<=focused.hudClient);assert.ok(focused.documentWidth<=focused.viewport);assert.ok(focused.button.left>=0&&focused.button.right<=focused.viewport&&focused.button.top>=0&&focused.button.bottom<=focused.hudHeight);row.steps.push({name:'mobile-speed-focused-after-tick',...focused});await snap(page,row,'mobile-speed-focused');row.status='passed';row.metrics=metrics;
 }catch(error){row.status='failed';row.failure=String(error.stack||error);try{await snap(page,row,'failure');}catch{}throw error;}finally{await context.close();}
}
async function main(){
 fs.mkdirSync(OUT,{recursive:true});let baseUrl;
 try{report.source=sourceManifest();if(report.source.errors.length)throw new Error('Initial source manifest incomplete: '+JSON.stringify(report.source.errors));baseUrl=await startServer();browser=await playwright[ENGINE].launch({...(BROWSER?{executablePath:BROWSER}:{}),headless:true,...(ENGINE==='chromium'?{args:['--no-sandbox']}:{})});report.browser=browser.version();report.baseUrl=baseUrl;const selected=process.env.SOC_PROVIDER_BROWSER_JOURNEYS?.split(',').map(x=>x.trim()).filter(Boolean);const validJourneys=[...plans.map(x=>x.id),...['enterprise','government','defence'].map(x=>'mission-'+x),'ownership-persistence','keyboard-smb-opening','assurance-quote-preview','mobile-hud-opening','product-retirement',...Object.keys(productRecipes).map(x=>'product-'+x)];if(selected?.some(x=>!validJourneys.includes(x)))throw new Error('Unknown selected journey ID');report.selection=selected||'full-matrix';for(const spec of plans.filter(x=>!selected||selected.includes(x.id)))await runJourney(baseUrl,spec);for(const scenario of ['enterprise','government','defence'])if(!selected||selected.includes(`mission-${scenario}`))await runMissionJourney(baseUrl,scenario);if(!selected||selected.includes('ownership-persistence'))await runOwnershipAndPersistence(baseUrl);if(!selected||selected.includes('keyboard-smb-opening'))await runKeyboardJourney(baseUrl);if(!selected||selected.includes('assurance-quote-preview'))await runAssuranceQuoteJourney(baseUrl);if(!selected||selected.includes('mobile-hud-opening'))await runMobileHudJourney(baseUrl);const explicitProducts=process.env.SOC_PROVIDER_BROWSER_PRODUCTS?.split(',').map(x=>x.trim()).filter(Boolean);if(explicitProducts?.some(x=>!productRecipes[x]))throw new Error('Unknown selected product ID');const productSelection=explicitProducts||(!selected?Object.keys(productRecipes):selected.filter(x=>x.startsWith('product-')&&x!=='product-retirement').map(x=>x.slice(8)));for(const recipeId of productSelection)await runProductJourney(baseUrl,recipeId);if(!selected||selected.includes('product-retirement'))await runProductJourney(baseUrl,'ms-workplace-calling',{retirement:true});report.status='passed';}
 catch(error){report.status='failed';report.error=String(error.stack||error);process.exitCode=1;}
 finally{
  for(const [operation,close] of [['browser-close',async()=>{if(browser)await browser.close();}],['server-close',async()=>{if(server?.listening)await new Promise((resolve,reject)=>server.close(error=>error?reject(error):resolve()));}]])try{await close();}catch(error){report.finalizationErrors??=[];report.finalizationErrors.push({operation,error:String(error.stack||error)});if(report.status==='passed')report.status='failed';process.exitCode=1;}
  writeFinalReport();
 }
}
main();
